// #6a993d794918a5e83bc3231b (#c3231b) AC3, треб.2 — «שכחתי סיסמה»: одинаковый экран для существующего и несуществующего адреса (кейс AUTH-LG-004).
// spec: specs/auth-login.md (3.1, 3.2) · seed: tests/seed.spec.ts (гость).
// 3.1 — несуществующий адрес: письмо не отправляется, но запрос к /auth/v1/recover реальный (лимиты Supabase) — не @prod-safe.
// 3.2 — ОТПРАВЛЯЕТ НАСТОЯЩЕЕ ПИСЬМО на тестовый адрес @example.com (QA_USER_PASSPEND_EMAIL из .qa/accounts.env),
//       чтобы не упираться в лимит писем — только по флагу, не чаще 1 раза за прогон:
//         QA_RUN_RESET_MAIL=1 npx playwright test tests/auth-login/forgot-password-same-message.spec.ts --project=tests --workers=1
// Письмо и ссылка сброса (AUTH-LG-005) — ручные.
import * as dotenv from 'dotenv';
import * as path from 'path';
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { NONEXISTENT_EMAIL } from '../support/auth-mocks';

dotenv.config({ path: path.resolve(__dirname, '../../../accounts.env') });
const EXISTING_TEST_EMAIL = process.env.QA_USER_PASSPEND_EMAIL;

/** /login → «שכחתי סיסמה» → отправка адреса; возвращает HTTP-статус /auth/v1/recover и текст экрана. */
async function requestReset(page: Page, email: string) {
  await page.goto('/login');
  await page.getByRole('link', { name: 'שכחתי סיסמה' }).click();
  await page.waitForURL((u) => u.pathname === '/forgot-password');
  await expect(page.getByRole('heading', { level: 1, name: 'איפוס סיסמה' })).toBeVisible();

  await page.getByRole('textbox', { name: 'מייל' }).fill(email);
  const responsePromise = page.waitForResponse((r) => /\/auth\/v1\/recover/.test(r.url()) && r.request().method() === 'POST');
  await page.getByRole('button', { name: 'שליחת קישור לאיפוס' }).click();
  const status = (await responsePromise).status();

  // AC3 «וההודעה במסך זהה גם כאשר המייל אינו קיים».
  await expect(page.getByRole('heading', { level: 1, name: 'בדקו את תיבת המייל' })).toBeVisible();
  await expect(page.getByTestId('recovery-failed')).toHaveCount(0);
  const card = page.getByTestId('auth-card');
  await expect(card).toContainText('אם המייל רשום במערכת, שלחנו אליו קישור לבחירת סיסמה חדשה. הקישור תקף למשך 30 דקות ולשימוש אחד בלבד.');
  await expect(card).toContainText('המייל שהזנתם');
  await expect(card).toContainText(email);
  // Текст экрана без введённого адреса — для сравнения двух случаев.
  const text = (await card.innerText()).replace(email, '<email>').replace(/\s+/g, ' ').trim();
  return { status, text };
}

test.describe('Восстановление пароля — одинаковый ответ (#6a993d794918a5e83bc3231b)', () => {
  test('гость: несуществующий адрес → «בדקו את תיבת המייל», без ошибки @desktop #6a993d794918a5e83bc3231b', async ({ page }) => {
    const { status } = await requestReset(page, NONEXISTENT_EMAIL);
    expect(status).toBe(200);
  });

  test('гость: существующий и несуществующий адрес — одинаковый экран и статус ответа @desktop @data @reset-mail #6a993d794918a5e83bc3231b', async ({ asUser }) => {
    test.skip(!process.env.QA_RUN_RESET_MAIL, 'отправляет настоящее письмо — запуск только с QA_RUN_RESET_MAIL=1, не чаще 1 раза за прогон');
    test.skip(!EXISTING_TEST_EMAIL || !/@example\.com$/i.test(EXISTING_TEST_EMAIL), 'нет тестового адреса @example.com в QA_USER_PASSPEND_EMAIL (.qa/accounts.env)');

    const missing = await requestReset(await asUser('guest'), NONEXISTENT_EMAIL);
    const existing = await requestReset(await asUser('guest'), EXISTING_TEST_EMAIL!);
    expect(existing.status, 'статус /auth/v1/recover одинаковый').toBe(missing.status);
    expect(existing.text, 'текст экрана одинаковый').toBe(missing.text);
  });
});
